package vn.rtr.aeris.cockpit82;
import java.net.URI;import java.util.*;
public final class ResourcePolicy {
 private static final Set<String> ASSETS=new HashSet<>(Arrays.asList("/assets/camera-concept.png","/cockpit.css","/cockpit.mjs","/controls82.mjs","/fonts/Barlow-Bold.ttf","/fonts/Barlow-Medium.ttf","/fonts/Barlow-SemiBold.ttf","/glass.css","/index.html","/islands82.css","/mock-model.mjs","/native82.css","/runtime82.mjs","/transport82.mjs","/workflow/binding.mjs","/workflow/capsule.mjs","/workflow/core/airspace.mjs","/workflow/core/common.mjs","/workflow/core/geometry.mjs","/workflow/editor.mjs","/workflow/fixture.mjs","/workflow/journey.mjs","/workflow/mock.mjs","/workflow/pins.mjs","/workflow/preflight/adapter.mjs","/workflow/preflight/bytes.mjs","/workflow/preflight/definitions.mjs","/workflow/preflight/parameter.mjs","/workflow/preflight/profile.mjs","/workflow/preflight/sha256.mjs","/workflow/preflight/wire.mjs","/workflow/route.mjs","/workflow/vendor/compiler.mjs","/workflow/vendor/survey.mjs","/workflow/workflow.mjs"));
 public static boolean allowed(String raw){try{URI u=new URI(raw);return "https".equals(u.getScheme())&&"native82.aeris.invalid".equals(u.getRawAuthority())&&u.getRawQuery()==null&&u.getRawFragment()==null&&ASSETS.contains(u.getRawPath())&&u.getRawPath().equals(u.getPath());}catch(Exception e){return false;}}
}
